var t=`0319-quiche-lorraine`;var i=`world-0319`;var o=`FR`;var a=`western-europe`;var r=4;var s=60;var l={en:`Quiche Lorraine`,ua:`Кіш лорен`};var d={en:`A traditional France dish made with shortcrust pastry, bacon, chicken egg, heavy cream. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Франція. Основні інгредієнти: пісочне тісто, бекон, куряче яйце, вершки високої жирності. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var u=[{en:`Roll or press the prepared dough evenly into the desired thickness and shape.`,ua:`Розкачайте або розпластайте підготовлене тісто рівномірним шаром потрібної товщини та форми.`,t:[`pressing`,`rolling-out-dough`],m:13,i:[[`shortcrust-pastry`,450,`g`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 7 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 7 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:7,i:[[`bacon`,220,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:5,i:[[`chicken-egg`,4,`pcs`],[`heavy-cream`,380,`ml`],[`ground-nutmeg`,2,`g`],[`ground-black-pepper`,null,`to_taste`]]},{en:`Pour the bacon-and-cream custard into the pastry shell and bake at 180°C until lightly golden and set in the center; rest before slicing.`,ua:`Влийте вершково-яєчну заливку з беконом у тістову основу й випікайте при 180°C до золотавої скоринки та схоплення середини. Дайте трохи охолонути перед нарізанням.`,t:[`baking`],m:35,i:[]}];var h={slug:t,id:i,country:`FR`,region:a,servings:4,minutes:60,title:l,text:d,steps:u};export{o as country,h as default,i as id,s as minutes,a as region,r as servings,t as slug,u as steps,d as text,l as title};